import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import {
  Bell,
  Check,
  CreditCard,
  Globe2,
  Moon,
  Palette,
  Save,
  Store,
  Sun,
  Truck,
} from 'lucide-react';
import { useAdmin, type StoreSettings } from '../lib/store';
import { PageHeader, cn } from '../lib/ui';

const tabs = [
  { key: 'store', label: 'store', icon: Store },
  { key: 'delivery', label: 'delivery', icon: Truck },
  { key: 'payments', label: 'payments', icon: CreditCard },
  { key: 'appearance', label: 'appearance', icon: Palette },
  { key: 'notifications', label: 'notifications', icon: Bell },
] as const;

type TabKey = (typeof tabs)[number]['key'];

export const Settings = () => {
  const { t, i18n } = useTranslation();
  const { settings, saveSettings, notify } = useAdmin();
  const [tab, setTab] = useState<TabKey>('store');
  const [draft, setDraft] = useState<StoreSettings>(settings);

  const save = () => {
    saveSettings(draft);
    if (draft.theme !== 'system') {
      document.documentElement.classList.toggle('dark', draft.theme === 'dark');
      localStorage.setItem('maxshop-theme', draft.theme);
    }
    i18n.changeLanguage(draft.language);
    localStorage.setItem('maxshop-lang', draft.language);
    notify(t('saved'));
  };

  const reset = () => {
    setDraft(settings);
    notify('O\'zgarishlar bekor qilindi', 'info');
  };

  return (
    <div className="animate-fade-up">
      <PageHeader
        title={t('settingsTitle')}
        subtitle={t('settingsSubtitle')}
        action={
          <>
            <button className="btn-secondary btn-sm" onClick={reset}>{t('reset')}</button>
            <button className="btn-primary btn-sm" onClick={save}><Save size={15} /> {t('save')}</button>
          </>
        }
      />

      <div className="grid grid-cols-1 gap-5 lg:grid-cols-[240px_1fr]">
        <div className="card h-fit p-2">
          {tabs.map((item) => (
            <button
              key={item.key}
              onClick={() => setTab(item.key)}
              className={cn('nav-link w-full text-left', tab === item.key && 'nav-link-active')}
            >
              <item.icon size={17} />
              {t(item.label)}
            </button>
          ))}
        </div>

        <div className="space-y-5">
          {tab === 'store' && (
            <div className="card p-5 sm:p-6">
              <h2 className="font-display text-lg font-extrabold">{t('store')}</h2>
              <p className="mt-0.5 text-xs text-[var(--muted)]">Do'konning asosiy ma'lumotlari</p>
              <div className="mt-5 grid grid-cols-1 gap-4 sm:grid-cols-2">
                <div>
                  <label className="label">{t('storeName')}</label>
                  <input className="input" value={draft.storeName} onChange={(e) => setDraft({ ...draft, storeName: e.target.value })} />
                </div>
                <div>
                  <label className="label">{t('phone')}</label>
                  <input className="input" value={draft.phone} onChange={(e) => setDraft({ ...draft, phone: e.target.value })} />
                </div>
                <div>
                  <label className="label">{t('email')}</label>
                  <input className="input" value={draft.email} onChange={(e) => setDraft({ ...draft, email: e.target.value })} />
                </div>
                <div>
                  <label className="label">{t('workingHours')}</label>
                  <input className="input" value={draft.workingHours} onChange={(e) => setDraft({ ...draft, workingHours: e.target.value })} />
                </div>
                <div className="sm:col-span-2">
                  <label className="label">{t('address')}</label>
                  <input className="input" value={draft.address} onChange={(e) => setDraft({ ...draft, address: e.target.value })} />
                </div>
              </div>
            </div>
          )}

          {tab === 'delivery' && (
            <div className="card p-5 sm:p-6">
              <h2 className="font-display text-lg font-extrabold">{t('delivery')}</h2>
              <p className="mt-0.5 text-xs text-[var(--muted)]">Yetkazish shartlari va narxlari</p>
              <div className="mt-5 grid grid-cols-1 gap-4 sm:grid-cols-2">
                <div>
                  <label className="label">{t('freeDeliveryThreshold')} (so'm)</label>
                  <input type="number" className="input" value={draft.freeDeliveryThreshold} onChange={(e) => setDraft({ ...draft, freeDeliveryThreshold: Number(e.target.value) })} />
                </div>
                <div>
                  <label className="label">{t('deliveryFee')} (so'm)</label>
                  <input type="number" className="input" value={draft.deliveryFee} onChange={(e) => setDraft({ ...draft, deliveryFee: Number(e.target.value) })} />
                </div>
                <div>
                  <label className="label">{t('minOrderAmount')} (so'm)</label>
                  <input type="number" className="input" value={draft.minOrderAmount} onChange={(e) => setDraft({ ...draft, minOrderAmount: Number(e.target.value) })} />
                </div>
                <div>
                  <label className="label">Yetkazish radiusi</label>
                  <select className="select">
                    <option>Toshkent shahri</option>
                    <option>Toshkent viloyati</option>
                    <option>Butun O'zbekiston</option>
                  </select>
                </div>
              </div>
              <div className="mt-5 rounded-2xl bg-brand-500/10 p-4 text-xs font-semibold text-brand-700 dark:text-brand-300">
                💡 {draft.freeDeliveryThreshold.toLocaleString()} so'mdan yuqori buyurtmalar uchun yetkazish bepul bo'ladi.
              </div>
            </div>
          )}

          {tab === 'payments' && (
            <div className="card p-5 sm:p-6">
              <h2 className="font-display text-lg font-extrabold">{t('payments')}</h2>
              <p className="mt-0.5 text-xs text-[var(--muted)]">To'lov usullari va valyuta</p>
              <div className="mt-5 grid grid-cols-1 gap-4 sm:grid-cols-2">
                <div>
                  <label className="label">{t('currency')}</label>
                  <select className="select" value={draft.currency} onChange={(e) => setDraft({ ...draft, currency: e.target.value })}>
                    <option value="UZS">UZS — O'zbek so'mi</option>
                    <option value="USD">USD — Dollar</option>
                    <option value="RUB">RUB — Rubl</option>
                  </select>
                </div>
                <div>
                  <label className="label">QQS</label>
                  <select className="select">
                    <option>12%</option>
                    <option>15%</option>
                    <option>0%</option>
                  </select>
                </div>
              </div>
              <div className="mt-5 space-y-2">
                {[
                  { name: 'Payme', desc: 'Onlayn to\'lov', on: true },
                  { name: 'Click', desc: 'Onlayn to\'lov', on: true },
                  { name: 'Uzum Bank', desc: 'Onlayn to\'lov', on: true },
                  { name: 'Naqd pul', desc: 'Yetkazishda to\'lov', on: true },
                ].map((m) => (
                  <div key={m.name} className="flex items-center justify-between rounded-xl border p-3" style={{ borderColor: 'var(--border)' }}>
                    <div>
                      <p className="text-xs font-extrabold">{m.name}</p>
                      <p className="text-[10px] text-[var(--muted)]">{m.desc}</p>
                    </div>
                    <span className="flex h-6 w-11 items-center rounded-full bg-brand-500 p-0.5">
                      <span className="ml-auto h-5 w-5 rounded-full bg-white shadow" />
                    </span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {tab === 'appearance' && (
            <div className="card p-5 sm:p-6">
              <h2 className="font-display text-lg font-extrabold">{t('appearance')}</h2>
              <p className="mt-0.5 text-xs text-[var(--muted)]">Interfeys ko'rinishi va til</p>
              <div className="mt-5">
                <label className="label">{t('theme')}</label>
                <div className="grid grid-cols-3 gap-2">
                  {[
                    { key: 'light', label: t('light'), icon: Sun },
                    { key: 'dark', label: t('dark'), icon: Moon },
                    { key: 'system', label: t('system'), icon: Palette },
                  ].map((item) => (
                    <button
                      key={item.key}
                      onClick={() => setDraft({ ...draft, theme: item.key as StoreSettings['theme'] })}
                      className={cn(
                        'flex flex-col items-center gap-2 rounded-2xl border p-4 transition',
                        draft.theme === item.key ? 'border-brand-500 bg-brand-500/10 text-brand-600 dark:text-brand-400' : 'text-[var(--muted)] hover:bg-[var(--surface-2)]',
                      )}
                      style={{ borderColor: draft.theme === item.key ? undefined : 'var(--border)' }}
                    >
                      <item.icon size={20} />
                      <span className="text-xs font-bold">{item.label}</span>
                    </button>
                  ))}
                </div>
              </div>
              <div className="mt-5">
                <label className="label">{t('language')}</label>
                <div className="grid grid-cols-3 gap-2">
                  {[
                    { code: 'uz', label: "O'zbekcha" },
                    { code: 'ru', label: 'Русский' },
                    { code: 'en', label: 'English' },
                  ].map((l) => (
                    <button
                      key={l.code}
                      onClick={() => setDraft({ ...draft, language: l.code })}
                      className={cn(
                        'flex items-center justify-center gap-2 rounded-xl border py-2.5 text-xs font-bold transition',
                        draft.language === l.code ? 'border-brand-500 bg-brand-500/10 text-brand-600 dark:text-brand-400' : 'text-[var(--muted)]',
                      )}
                      style={{ borderColor: draft.language === l.code ? undefined : 'var(--border)' }}
                    >
                      <Globe2 size={14} /> {l.label}
                      {draft.language === l.code && <Check size={13} />}
                    </button>
                  ))}
                </div>
              </div>
              <div className="mt-5 rounded-2xl bg-[var(--surface-2)] p-4 text-xs text-[var(--muted)]">
                Tanlangan mavzu va til saqlangandan so'ng butun panelga qo'llaniladi.
              </div>
            </div>
          )}

          {tab === 'notifications' && (
            <div className="card p-5 sm:p-6">
              <h2 className="font-display text-lg font-extrabold">{t('notifications')}</h2>
              <p className="mt-0.5 text-xs text-[var(--muted)]">Qaysi bildirishnomalarni olishni tanlang</p>
              <div className="mt-5 space-y-2">
                {[
                  { key: 'orderNotifications' as const, title: t('orderNotifications'), desc: 'Yangi buyurtma kelganda darhol xabar' },
                  { key: 'promoNotifications' as const, title: t('promoNotifications'), desc: 'Aksiyalar va chegirmalar haqida' },
                ].map((n) => (
                  <div key={n.key} className="flex items-center justify-between rounded-xl border p-3" style={{ borderColor: 'var(--border)' }}>
                    <div>
                      <p className="text-xs font-extrabold">{n.title}</p>
                      <p className="text-[10px] text-[var(--muted)]">{n.desc}</p>
                    </div>
                    <button
                      onClick={() => setDraft({ ...draft, [n.key]: !draft[n.key] })}
                      className={cn('flex h-6 w-11 items-center rounded-full p-0.5 transition', draft[n.key] ? 'bg-brand-500' : 'bg-[var(--surface-3)]')}
                    >
                      <span className={cn('h-5 w-5 rounded-full bg-white shadow transition', draft[n.key] && 'ml-auto')} />
                    </button>
                  </div>
                ))}
                <div className="flex items-center justify-between rounded-xl border p-3" style={{ borderColor: 'var(--border)' }}>
                  <div>
                    <p className="text-xs font-extrabold">Telegram bot</p>
                    <p className="text-[10px] text-[var(--muted)]">Buyurtmalar Telegram orqali ham keladi</p>
                  </div>
                  <span className="badge bg-brand-500/15 text-brand-700 dark:text-brand-300">Ulangan</span>
                </div>
              </div>
            </div>
          )}

          <div className="flex justify-end gap-2">
            <button className="btn-secondary" onClick={reset}>{t('cancel')}</button>
            <button className="btn-primary" onClick={save}><Save size={16} /> {t('save')}</button>
          </div>
        </div>
      </div>
    </div>
  );
};
